window.RA_DATA = window.RA_DATA || {};
window.RA_DATA.lines = [
  { id: "clouds-s1", kind: "scene", book_id: "clouds", place_ids: ["gr-agora"], location: "Throughout", location_zh: "全剧", text_en: "Strepsiades, ruined by his son's love of horses, enrols at the Thinkery of Socrates, who hangs in a basket to study the heavens and worships the Clouds, to learn the argument that can win any case and cheat his creditors. Too stupid to learn, he sends his son instead, who comes back able to prove that a son may beat his father; Strepsiades burns the Thinkery down.", text_zh: "斯特瑞普西阿得斯被儿子爱马的嗜好弄得倾家荡产，便进了苏格拉底的“思想所”——苏格拉底吊在篮子里研究天象，崇拜云神——想学会能打赢任何官司的诡辩，好赖掉债主的钱。他太笨学不会，就让儿子去学，儿子回来后能论证儿子打老子天经地义；斯特瑞普西阿得斯一把火烧了思想所。", highlight_en: ["Thinkery"], highlight_zh: ["思想所"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Clouds" },
  { id: "symposium-s1", kind: "scene", book_id: "symposium", place_ids: ["gr-agora"], location: "Throughout", location_zh: "全篇", text_en: "At a dinner party in Athens to celebrate the playwright Agathon's victory, the guests agree to make speeches in praise of Love. Aristophanes tells how humans were once double creatures split in two, forever seeking their other half; Socrates repeats what the priestess Diotima taught him of the ladder from the love of one body to the love of beauty itself; then the drunken Alcibiades bursts in.", text_zh: "在雅典，为庆祝剧作家阿伽松获奖而办的一场宴会上，客人们约定轮流发表赞美爱神的演说。阿里斯托芬讲人原本是双体的，被劈成两半，从此永远寻找另一半；苏格拉底转述女祭司狄奥提玛教给他的道理：从爱一个身体，一级级上升到爱美本身；接着，喝醉的阿尔基比亚德闯了进来。", highlight_en: ["other half"], highlight_zh: ["另一半"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Symposium_(Plato)" },
  { id: "ethics-s1", kind: "scene", book_id: "ethics", place_ids: ["gr-lyceum"], location: "Books 1, 2 and 10", location_zh: "第一、二、十卷", text_en: "In lectures given at the Lyceum, Aristotle asks what the highest good of human life is and answers eudaimonia, flourishing, which comes from living according to virtue. Virtue is a habit, learned by practice, and lies in a mean between two extremes, as courage lies between cowardice and rashness; the happiest life of all is one spent in contemplation.", text_zh: "在吕克昂的讲课里，亚里士多德追问人生最高的善是什么，回答是“幸福”，即依照德性生活而得的繁荣兴旺。德性是一种习惯，靠实践养成，处于两个极端之间的中道，就像勇敢处在怯懦和鲁莽之间；最幸福的生活是沉思的生活。", highlight_en: ["a mean between two extremes"], highlight_zh: ["中道"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Nicomachean_Ethics" },
  { id: "sappho-s1", kind: "scene", book_id: "sappho", place_ids: ["gr-eresos"], location: "Fragments 1 and 31", location_zh: "残篇第一首与第三十一首", text_en: "Sappho calls on Aphrodite to come down again from heaven, as she has before, and help her win a girl who flees her. In another fragment she watches the girl she loves laughing with a man and feels her tongue break, a thin fire run under her skin, her eyes go blind and her ears roar, 'greener than grass', close to death.", text_zh: "萨福呼唤阿佛洛狄忒像从前那样再次从天上降临，帮她赢得一个躲着她的女孩。在另一首残篇里，她看着心爱的女孩和一个男人说笑，觉得舌头僵住，一股细火在皮肤下流窜，眼睛看不见，耳朵轰鸣，脸色“比青草还绿”，仿佛就要死去。", highlight_en: ["greener than grass"], highlight_zh: ["比青草还绿"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Sappho_31" },
  { id: "beggar-s1", kind: "scene", book_id: "beggar", place_ids: ["gr-kravara"], location: "Throughout", location_zh: "全篇", text_en: "Tzintzinas, a beggar from Kravara who has learnt every trick of his trade, arrives at a poor village on the Thessalian plain. Playing on the peasants' fear of the evil eye and the landlords, he cheats them, sets them against each other and profits from their misfortunes, a dark picture of rural Greece after Thessaly was joined to the kingdom.", text_zh: "津津纳斯是个精通各种行乞伎俩的克拉瓦拉乞丐，他来到色萨利平原上一个贫穷的村子。他利用农民对邪眼和地主的恐惧，骗他们、挑拨他们互斗，从他们的不幸中渔利。这是色萨利并入希腊王国之后乡村的一幅阴暗图景。", highlight_en: ["Tzintzinas"], highlight_zh: ["津津纳斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Andreas_Karkavitsas" },
  { id: "murderess-s1", kind: "scene", book_id: "murderess", place_ids: ["gr-skiathos"], location: "Throughout", location_zh: "全篇", text_en: "Hadoula, an old widow and midwife on Skiathos, sitting by the cradle of her sick newborn granddaughter, reflects that girls bring only dowries, sorrow and servitude, and strangles the baby. Convinced she is doing God's work, she kills other little girls, until the police pursue her across the island and she drowns 'halfway between divine and human justice'.", text_zh: "斯基亚索斯岛上的老寡妇、接生婆哈杜拉守在病弱的新生外孙女摇篮边，想到女孩带来的只有嫁妆、忧愁和奴役，就掐死了婴儿。她深信自己在替上帝做事，又杀了别的女婴，直到警察在岛上追捕她，她淹死在“神的正义和人的正义之间”。", highlight_en: ["between divine and human justice"], highlight_zh: ["神的正义和人的正义之间"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Murderess_(novel)" },
  { id: "makriyannis-s1", kind: "scene", book_id: "makriyannis", place_ids: ["gr-makrygianni"], location: "Throughout", location_zh: "全书", text_en: "Makriyannis tells his life from his poor childhood in Roumeli through the battles of the War of Independence, including the defence of the Mills at Lerna against Ibrahim Pasha, to the quarrels of the new kingdom, which he fights with the same fury. Writing in the language of the villages, with no schooling, he says he wrote so that the truth would not be lost.", text_zh: "马克里扬尼斯讲述他的一生：从鲁梅利贫苦的童年，到独立战争的一场场战斗——包括在勒尔纳的磨坊抵抗易卜拉欣帕夏——再到新王国的种种纷争，他同样愤怒地投入其中。他没上过学，用乡村的语言写作，说自己写下来，是为了不让真相湮没。", highlight_en: ["the Mills at Lerna"], highlight_zh: ["勒尔纳的磨坊"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Ioannis_Makriyannis" },
  { id: "honour-s1", kind: "scene", book_id: "honour-money", place_ids: ["gr-corfu-town"], location: "Throughout", location_zh: "全篇", text_en: "Rini, a young woman who works in a factory in the poor quarter of Mantouki, falls in love with Andreas, an idle young man of good family. His mother wants a dowry; Rini's mother scrapes it together, but when his family asks for more, Rini, seeing that he loves money more than her, refuses to buy him, and chooses to live by her own work and keep her honour her own way.", text_zh: "里妮是曼杜基贫民区一家工厂的年轻女工，爱上了出身体面、游手好闲的安德烈亚斯。他母亲要嫁妆；里妮的母亲东拼西凑凑齐了，可他家又要更多，里妮看出他爱钱胜过爱她，拒绝用钱买下他，宁愿靠自己做工过活，用自己的方式守住尊严。", highlight_en: ["refuses to buy him"], highlight_zh: ["拒绝用钱买下他"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Konstantinos_Theotokis" },
  { id: "tomb-s1", kind: "scene", book_id: "life-in-tomb", place_ids: ["gr-sykamineas"], location: "Throughout", location_zh: "全书", text_en: "Sergeant Antonis Kostoulas, a young man from Lesbos, writes letters he never sends to the girl he loves, from the trenches of the Macedonian front in the First World War: the mud, the lice, the rats, the deaths of his comrades, and a small red poppy he finds in no man's land. The letters are never sent.", text_zh: "来自莱斯博斯岛的年轻中士安东尼斯·科斯图拉斯，在一战马其顿前线的战壕里，给心爱的姑娘写了一封又一封没有寄出的信：泥浆、虱子、老鼠、战友的死，还有他在两军之间的无人地带找到的一朵小小的红罂粟。这些信一封也没有寄出。", highlight_en: ["red poppy"], highlight_zh: ["红罂粟"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Stratis_Myrivilis" },
  { id: "schoolmistress-s1", kind: "scene", book_id: "schoolmistress", place_ids: ["gr-mytilene"], location: "Throughout", location_zh: "全书", text_en: "Home in Mytilene after the disaster in Asia Minor, the young officer Leonis Drivas keeps his promise to his dead friend Vranas and visits his widow, Sappho, a schoolteacher with golden eyes. He falls in love with her and cannot free himself of the feeling that he is betraying the dead man.", text_zh: "小亚细亚惨败之后回到米蒂利尼，年轻军官莱昂尼斯·德里瓦斯兑现对亡友弗拉纳斯的承诺，去看望他的遗孀萨福——一位有着金色眼睛的女教师。他爱上了她，却始终摆脱不了背叛死者的感觉。", highlight_en: ["golden eyes"], highlight_zh: ["金色眼睛"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Stratis_Myrivilis" },
  { id: "seferis-s1", kind: "scene", book_id: "seferis", place_ids: ["gr-asine"], location: "The King of Asine", location_zh: "《阿西尼王》", text_en: "All morning the poet and his companion search the citadel of Asine for the king Homer names only once, 'Asine', touching the stones, looking at the sea below. Under the mask they find nothing: only a void that goes with us everywhere, and the name of a king who vanished.", text_zh: "整个上午，诗人和同伴在阿西尼的城堡里寻找荷马只提过一次的国王，“阿西尼”，抚摸石头，望着下面的大海。面具下面什么也没有：只有一片处处与我们同在的空无，和一个消失了的国王的名字。", highlight_en: ["a void"], highlight_zh: ["空无"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Giorgos_Seferis" },
  { id: "zorba-s1", kind: "scene", book_id: "zorba", place_ids: ["gr-kazantzakis-grave"], location: "Throughout and ending", location_zh: "全书与结尾", text_en: "A young bookish writer, the Boss, takes on the wild old Macedonian Alexis Zorba to run a lignite mine on the Cretan coast. Zorba drinks, plays the santuri, seduces the old French courtesan Madame Hortense and teaches him to live. When the cable railway they built collapses at its opening, Zorba leads him in a dance on the beach.", text_zh: "一个书生气的年轻作家——“老板”——雇了狂放的马其顿老人阿莱克西斯·佐巴，在克里特海边经营褐煤矿。佐巴喝酒、弹桑图里琴、勾引年老的法国交际花奥尔唐斯太太，教他怎么活。他们修的索道在启用当天就垮了，佐巴拉着他在海滩上跳起舞来。", highlight_en: ["dance on the beach"], highlight_zh: ["在海滩上跳起舞来"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Zorba_the_Greek" },
  { id: "freedom-s1", kind: "scene", book_id: "freedom-or-death", place_ids: ["gr-heraklion"], location: "Throughout", location_zh: "全书", text_en: "In Megalokastro, during the Cretan revolt of 1889 against the Turks, the fierce Captain Michalis is torn between his country and his desire for Eminé, a Circassian woman married to his Turkish blood-brother Nuri Bey. When he fails his duty in battle, he goes back to the mountains to die fighting, crying 'Freedom or death'.", text_zh: "1889 年克里特人起义反抗土耳其统治，在“大城堡”里，暴烈的米哈利斯船长在祖国和对埃米内的欲望之间撕扯——她是切尔克斯女子，嫁给了他的土耳其结义兄弟努里贝伊。他在战斗中失职后，回到山里战斗到死，高喊着“自由或死亡”。", highlight_en: ["Freedom or death"], highlight_zh: ["自由或死亡"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Freedom_or_Death" },
  { id: "axion-s1", kind: "scene", book_id: "axion-esti", place_ids: ["gr-heraklion"], location: "Genesis; The Passion; The Gloria", location_zh: "《创世》《受难》《荣耀》", text_en: "Elytis builds his poem like an Orthodox liturgy: in Genesis the poet's world is created out of the Aegean light; in The Passion he lives through the war on the Albanian front, the occupation and the civil war; and in the Gloria he praises everything, small and great, that is 'worthy'. Theodorakis set it to music in 1964.", text_zh: "埃利蒂斯把这首诗写成东正教礼拜仪式的结构：《创世》里，诗人的世界从爱琴海的光中诞生；《受难》里，他经历阿尔巴尼亚前线的战争、占领和内战；《荣耀》里，他赞美一切大大小小“理所当然”的事物。提奥多拉基斯 1964 年为它谱了曲。", highlight_en: ["Aegean light"], highlight_zh: ["爱琴海的光"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Axion_Esti" },
  { id: "chimera-s1", kind: "scene", book_id: "great-chimera", place_ids: ["gr-ermoupoli"], location: "Throughout", location_zh: "全书", text_en: "Marina, a young Frenchwoman in love with the sea, marries Yannis Refenes, the son of a Syros shipping family, and comes to live in his mother's house in Ermoupoli. The island's closed world, her passion for her husband's brother and the loss of her child drive her step by step towards her own destruction.", text_zh: "热爱大海的年轻法国女子玛丽娜嫁给了锡罗斯航运世家的儿子扬尼斯·雷费内斯，住进他母亲在埃尔穆波利的宅子。岛上封闭的世界、她对丈夫弟弟的激情，还有孩子的死，一步步把她推向毁灭。", highlight_en: ["Marina"], highlight_zh: ["玛丽娜"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/M._Karagatsis" },
  { id: "ritsos-s1", kind: "scene", book_id: "ritsos", place_ids: ["gr-monemvasia"], location: "The Moonlight Sonata", location_zh: "《月光奏鸣曲》", text_en: "On a spring evening, in a large room of an old house, a woman in black, no longer young, talks to a young man who has come to visit her while the moon shines on the city. She speaks of loneliness, of age, of the house that has become her prison, and again and again begs him: 'Let me come with you.'", text_zh: "一个春天的傍晚，在一座老房子的大房间里，一个上了年纪的黑衣女人对来访的年轻人说话，月光照着城市。她说起孤独、衰老，说这座房子成了她的牢笼，一遍又一遍恳求他：“让我跟你一起走吧。”", highlight_en: ["Let me come with you"], highlight_zh: ["让我跟你一起走吧"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Yannis_Ritsos" },
  { id: "wedding-s1", kind: "scene", book_id: "third-wedding", place_ids: ["gr-athens"], location: "Throughout", location_zh: "全书", text_en: "Two Athenian women take turns to talk: Nina, who has married three times, and her friend Ekavi, a proud widow at odds with her daughter. Their stories run through the interwar years, the hunger of the German occupation and the civil war, up to Nina's third wedding. History reaches them only as gossip, shortages and quarrels at the kitchen table.", text_zh: "两个雅典女人轮流开口：结过三次婚的尼娜，和她的朋友、与女儿不和的骄傲寡妇赫卡比。她们的故事从两次大战之间，讲到德国占领时期的饥荒和内战，一直讲到尼娜第三次结婚。历史只以闲话、短缺和餐桌上的争吵进入她们的生活。", highlight_en: ["third wedding"], highlight_zh: ["第三次结婚"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Costas_Taktsis" },
  { id: "daughter-s1", kind: "scene", book_id: "the-daughter", place_ids: ["gr-athens"], location: "Throughout", location_zh: "全书", text_en: "In a small town under the Occupation, Roubini's mother Asimina, whose husband is presumed dead, takes up with the Italian soldiers to keep her children alive. After liberation the town condemns her as a whore and a traitor. Roubini, who grows up to be a bit-part actress, tells the story in her own sharp voice, never ashamed of her mother.", text_zh: "占领时期的一座小城里，鲁比妮的母亲阿西米娜以为丈夫死了，为了让孩子们活下去，和意大利士兵做了情人。解放后，城里人骂她是娼妇和叛徒。长大后成了跑龙套演员的鲁比妮，用她自己尖锐的声音讲出这个故事，从来不为母亲感到羞耻。", highlight_en: ["Italian soldiers"], highlight_zh: ["意大利士兵"], status: "draft", fact_source: "https://www.supersummary.com/the-daughter/summary/" },
  { id: "smalltown-s1", kind: "scene", book_id: "end-small-town", place_ids: ["gr-ioannina"], location: "Sabethai Kabilis and other stories", location_zh: "《萨贝泰·卡比利斯》等篇", text_en: "Hatzis writes about the people of a provincial Greek town as the old world ends: a poor Jewish shopkeeper, Sabethai Kabilis, whose life and community are swept away; craftsmen and small traders; the old notables who cannot see that their time has gone. The town is unnamed, but readers have always recognised his native Ioannina.", text_zh: "哈齐斯写一座希腊外省小城的人们，在旧世界终结之际的命运：贫穷的犹太店主萨贝泰·卡比利斯，他的生活和他的社区被一扫而空；手艺人和小商贩；还有看不出自己时代已过的老名流。小城没有点名，但读者一向认得出这是他的故乡约阿尼纳。", highlight_en: ["Sabethai Kabilis"], highlight_zh: ["萨贝泰·卡比利斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Dimitris_Hatzis" },
  { id: "ismail-s1", kind: "scene", book_id: "ismail-ferik", place_ids: ["gr-lasithi"], location: "Throughout", location_zh: "全书", text_en: "A Cretan boy is carried off as a captive to Egypt during the War of Independence, made a Muslim and raised to become a general and minister. Decades later he returns to Crete at the head of an army to put down the revolt of 1866, on the other side of which stands his own brother, taken with him as a boy; between the two homelands he belongs to neither.", text_zh: "独立战争期间，一个克里特男孩被掳到埃及，改信伊斯兰教，长大后成了将军和大臣。几十年后，他率军回到克里特镇压 1866 年的起义，而站在起义一方的，正是小时候和他一起被掳走的亲兄弟；夹在两个故乡之间，他哪一个都不属于。", highlight_en: ["revolt of 1866"], highlight_zh: ["1866 年的起义"], status: "draft", fact_source: "https://bookmarkedplaces.com/the-life-of-ismail-ferik-pasha-by-rhea-galanaki/" },
  { id: "twilight-s1", kind: "scene", book_id: "twilight-return", place_ids: ["gr-sochos"], location: "Throughout", location_zh: "全书", text_en: "In ten interlocking tales, Zateli follows the household of Christoforos, married in turn to Petroula, Eftha and Persa, and of his restless son Hesychios, across four generations in a northern Greek town around 1900, where folklore, dreams and ancient myth mingle with everyday life.", text_zh: "扎泰利用十个相互交织的故事，讲述 1900 年前后希腊北方一座小城里赫里斯托福罗斯的一家：他先后娶了佩特鲁拉、埃夫塔和佩尔莎；还有他不安分的儿子伊西希奥斯，一共四代人。民间传说、梦境和古老神话与日常生活交织在一起。", highlight_en: ["ten interlocking tales"], highlight_zh: ["十个相互交织的故事"], status: "draft", fact_source: "https://yalebooks.yale.edu/9780300200713/at-twilight-they-return" },
  { id: "england-s1", kind: "scene", book_id: "little-england", place_ids: ["gr-andros"], location: "Throughout", location_zh: "全书", text_en: "In the 1930s, on Andros, Orsa Saltaferou loves the sailor Spyros Maltambes, but her ambitious mother marries her to a sea captain, Nikolas, and gives Spyros to her younger sister Moscha. With the men always away at sea, the sisters live side by side in silence and jealousy, while the war and the sinking of ships bring news of death.", text_zh: "30 年代的安德罗斯岛，奥尔莎·萨尔塔费鲁爱着水手斯皮罗斯·马尔坦贝斯，可她野心勃勃的母亲把她嫁给了船长尼古拉斯，又把斯皮罗斯许给了妹妹莫斯卡。男人们常年在海上，姐妹俩比邻而居，在沉默和嫉妒中过日子，战争和沉船不断带来死讯。", highlight_en: ["Orsa"], highlight_zh: ["奥尔莎"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Little_England" },
  { id: "z-s1", kind: "scene", book_id: "z", place_ids: ["gr-thessaloniki"], location: "Throughout", location_zh: "全书", text_en: "In a northern Greek city, a popular left-wing deputy and doctor speaks at a peace rally despite threats, and as he leaves he is struck on the head by a thug riding a three-wheeled truck, while the police look on. A young examining magistrate refuses to accept the official version that it was a traffic accident, and uncovers a conspiracy reaching up to the generals.", text_zh: "在希腊北方一座城市，一位深受欢迎的左翼议员兼医生不顾威胁在和平集会上演讲，离开时被一个坐在三轮卡车上的暴徒击中头部，警察就在一旁看着。一位年轻的预审法官拒绝接受“交通事故”的官方说法，揭开了一个一直通到将军们的阴谋。", highlight_en: ["three-wheeled truck"], highlight_zh: ["三轮卡车"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Z_(novel)" },
  { id: "thread-s1", kind: "scene", book_id: "the-thread", place_ids: ["gr-thessaloniki"], location: "Throughout", location_zh: "全书", text_en: "In 1917 a fire destroys much of Thessaloniki, and the newborn Dimitri Komninos is carried to safety. Five years later, in the flood of refugees from Smyrna, little Katerina is separated from her mother and finds a home in a house shared with a Jewish family. The two grow up and fall in love through the occupation, the deportation of the Jews and the civil war.", text_zh: "1917 年一场大火烧毁了塞萨洛尼基的大半，刚出生的季米特里·科姆尼诺斯被抱出了火海。五年后，在从士麦那涌来的难民潮中，小卡捷琳娜和母亲失散，在一座与犹太人家庭合住的房子里找到了家。两人在占领、犹太人被驱逐和内战中长大、相爱。", highlight_en: ["fire"], highlight_zh: ["大火"], status: "draft", fact_source: "https://www.goodreads.com/en/book/show/11468237" },
  { id: "family-s1", kind: "scene", book_id: "my-family", place_ids: ["gr-perama-corfu"], location: "Throughout", location_zh: "全书", text_en: "Tired of the English rain, Mrs Durrell takes her four children to Corfu in 1935. While Larry writes and complains, Leslie shoots, and Margo battles her acne, ten-year-old Gerry roams the island with his dog Roger, studying everything that crawls. When he hides a mother scorpion and her babies in a matchbox, they escape at the lunch table and set off a family uproar.", text_zh: "受够了英国的雨，达雷尔太太 1935 年带着四个孩子搬到科孚岛。拉里写作、抱怨，莱斯利打猎，玛戈和青春痘作战，十岁的杰里则带着狗罗杰满岛游荡，研究一切会爬的东西。他把一只母蝎和小蝎子藏在火柴盒里，结果它们在午餐桌上逃了出来，一家人乱成一团。", highlight_en: ["matchbox"], highlight_zh: ["火柴盒"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/My_Family_and_Other_Animals" },
  { id: "prospero-s1", kind: "scene", book_id: "prosperos-cell", place_ids: ["gr-kalami"], location: "Throughout", location_zh: "全书", text_en: "From the white house at Kalami, Lawrence Durrell keeps a diary of the island he and his wife N. fell in love with: swimming off the rocks, olive harvests and saints' festivals, long talks with the island's characters about Corfu as the island of Shakespeare's Tempest, until the coming of war ends it.", text_zh: "在卡拉米的白屋里，劳伦斯·达雷尔为他和妻子 N. 爱上的这座岛记日记：从礁石上跳海游泳，橄榄收获和圣徒节庆，和岛上各色人物长谈——谈科孚就是莎士比亚《暴风雨》里的那座岛——直到战争到来，一切结束。", highlight_en: ["Tempest"], highlight_zh: ["暴风雨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lawrence_Durrell" },
  { id: "venus-s1", kind: "scene", book_id: "marine-venus", place_ids: ["gr-rhodes"], location: "Throughout", location_zh: "全书", text_en: "Posted to Rhodes at the end of the Second World War, Durrell writes of the island and its friends: a marble Venus worn smooth by the sea, the Knights' medieval town, the ruins of Lindos and Kamiros, and the islanders slowly returning to life after the war.", text_zh: "二战结束时被派到罗得岛，达雷尔写下这座岛和岛上的朋友：一尊被海水磨得光滑的大理石维纳斯、骑士团的中世纪古城、林多斯和卡米罗斯的遗址，还有战后慢慢恢复生机的岛民。", highlight_en: ["marble Venus"], highlight_zh: ["大理石维纳斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Reflections_on_a_Marine_Venus" },
  { id: "colossus-s1", kind: "scene", book_id: "colossus", place_ids: ["gr-epidaurus"], location: "Epidaurus", location_zh: "埃皮达鲁斯一节", text_en: "Invited by Lawrence Durrell in 1939, Henry Miller travels through Greece with the poet George Katsimbalis, the 'Colossus', a great talker who, on a hill above Athens, crows like a rooster until the cocks of Attica answer him. At Epidaurus Miller feels the stillness of the theatre and the healing power of the place, and believes he has found peace.", text_zh: "1939 年应劳伦斯·达雷尔之邀，亨利·米勒和诗人卡齐姆巴利斯——“巨人”——一起游历希腊；这个大话匣子在雅典城外的山上学公鸡打鸣，直到阿提卡的公鸡都啼叫起来回应他。在埃皮达鲁斯，米勒感受到剧场的宁静和这个地方的治愈力量，相信自己找到了平静。", highlight_en: ["cocks of Attica"], highlight_zh: ["公鸡都啼叫起来"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Colossus_of_Maroussi" },
  { id: "mani-s1", kind: "scene", book_id: "mani", place_ids: ["gr-kardamyli"], location: "Throughout", location_zh: "全书", text_en: "Walking and sailing through the far south of the Peloponnese, Leigh Fermor describes the Mani: villages of stone towers built for clan wars that lasted generations, the dirges women improvised over the dead, the saints and mermaids of local legend, and Kardamyli by the sea, where he would one day make his home.", text_zh: "利·弗莫尔徒步和乘船走遍伯罗奔尼撒最南端，描写马尼：为延续几代人的家族战争而建的石头塔楼村落、女人们在死者身边即兴吟唱的挽歌、当地传说里的圣徒和美人鱼，还有海边的卡尔达米利——有一天他会在那里安家。", highlight_en: ["stone towers"], highlight_zh: ["石头塔楼"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Mani:_Travels_in_the_Southern_Peloponnese" },
  { id: "magus-s1", kind: "scene", book_id: "magus", place_ids: ["gr-spetses"], location: "Part 2", location_zh: "第二部", text_en: "Bored and selfish, Nicholas Urfe takes a teaching post on the Greek island of Phraxos and is drawn to the villa Bourani, where the rich old Maurice Conchis stages a series of masques, stories and seductions around him, including the mysterious twins Lily and Rose. As each illusion is replaced by another, Nicholas cannot tell what is real.", text_zh: "百无聊赖又自私的尼古拉斯·厄尔夫到希腊的弗拉克索斯岛教书，被吸引到布拉尼别墅；富有的老人莫里斯·康奇斯围绕着他上演一连串假面戏、故事和诱惑，其中有神秘的双胞胎莉莉和罗斯。一个幻象被另一个取代，尼古拉斯再也分不清什么是真的。", highlight_en: ["Bourani"], highlight_zh: ["布拉尼"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Magus_(novel)" },
  { id: "corelli-s1", kind: "scene", book_id: "corelli", place_ids: ["gr-argostoli"], location: "Throughout", location_zh: "全书", text_en: "In 1941 Italian troops occupy Kefalonia, and the cheerful, music-loving Captain Antonio Corelli is billeted in the house of Dr Iannis and his daughter Pelagia, who is engaged to a fisherman fighting on the mainland. She falls in love with Corelli and his mandolin. In 1943, after Italy surrenders, the Germans massacre thousands of Italian soldiers on the island.", text_zh: "1941 年意大利军队占领凯法利尼亚岛，开朗、热爱音乐的安东尼奥·科莱利上尉被安排住在伊安尼斯医生和他女儿佩拉吉娅家里；佩拉吉娅已经和一个在大陆打仗的渔夫订了婚。她爱上了科莱利和他的曼陀林。1943 年意大利投降后，德军在岛上屠杀了数千名意大利士兵。", highlight_en: ["mandolin"], highlight_zh: ["曼陀林"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Captain_Corelli%27s_Mandolin" },
  { id: "island-s1", kind: "scene", book_id: "the-island", place_ids: ["gr-spinalonga"], location: "Throughout", location_zh: "全书", text_en: "Alexis, a young Englishwoman, visits Plaka, her mother's village in Crete, and an old friend of the family tells her the secret her mother has kept: her great-grandmother Eleni, a teacher, caught leprosy and was sent across the water to Spinalonga, and later her daughter Maria followed, while the family on the shore watched the island for years.", text_zh: "年轻的英国女子亚历克西斯来到母亲在克里特的家乡普拉卡，一位家族老友向她讲出了母亲一直守着的秘密：她的曾外祖母、教师埃莱妮染上麻风，被送过海峡到了斯皮纳隆加；后来她的女儿玛丽亚也被送了过去，岸上的家人多年来一直望着那座岛。", highlight_en: ["Spinalonga"], highlight_zh: ["斯皮纳隆加"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Island_(Hislop_novel)" },
  { id: "king-s1", kind: "scene", book_id: "king-must-die", place_ids: ["gr-knossos"], location: "The Cretan books", location_zh: "克里特部分", text_en: "Theseus, the young prince of Troezen, comes to Athens and, to free his people from the tribute, volunteers to go to Crete among the youths sent to the bull-ring at Knossos. There he trains a team of bull-leapers who survive by trusting one another, wins the love of the princess Ariadne, and is in the palace when an earthquake brings down the House of the Axe.", text_zh: "特罗曾的年轻王子忒修斯来到雅典，为了让人民摆脱进贡，自愿跟着少男少女一起去克里特，进克诺索斯的斗牛场。他在那里训练出一支靠彼此信任活下来的跃牛队，赢得了公主阿里阿德涅的爱；一场地震震塌“双斧之宫”时，他就在宫里。", highlight_en: ["bull-leapers"], highlight_zh: ["跃牛队"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_King_Must_Die" },
  { id: "wine-s1", kind: "scene", book_id: "last-of-wine", place_ids: ["gr-agora"], location: "Throughout", location_zh: "全书", text_en: "Alexias, a young Athenian of good family, grows up during the long war with Sparta, becomes one of the young men around Socrates, and loves the noble Lysis. He fights at sea and on land, lives through the siege and surrender of Athens and the rule of the Thirty Tyrants, and sees the city's golden age drain away.", text_zh: "出身名门的雅典青年亚历克西亚斯在与斯巴达的漫长战争中长大，成了苏格拉底身边的年轻人之一，爱上了高贵的吕西斯。他在海上和陆上作战，经历了雅典被围、投降和三十僭主的统治，眼看着城邦的黄金时代一点点流逝。", highlight_en: ["Socrates"], highlight_zh: ["苏格拉底"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Last_of_the_Wine" },
  { id: "achilles-s1", kind: "scene", book_id: "song-of-achilles", place_ids: ["gr-pelion"], location: "The years on Pelion", location_zh: "佩利翁山的岁月", text_en: "Exiled to the court of King Peleus after accidentally killing a boy, the awkward Patroclus becomes the companion of the golden prince Achilles. When Achilles is sent to be taught by the centaur Chiron on Mount Pelion, Patroclus follows him, and in the mountain years of hunting, music and medicine they fall in love, before the war at Troy calls them away.", text_zh: "失手杀了一个男孩后，笨拙的帕特洛克罗斯被流放到珀琉斯王的宫廷，成了金发王子阿喀琉斯的伙伴。阿喀琉斯被送到佩利翁山跟半人马喀戎学习，帕特洛克罗斯追随而去；在山上狩猎、奏乐、学医的岁月里，两人相爱了，直到特洛伊战争把他们召走。", highlight_en: ["Mount Pelion"], highlight_zh: ["佩利翁山"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Song_of_Achilles" },
  { id: "circe-s1", kind: "scene", book_id: "circe", place_ids: ["gr-knossos"], location: "The birth of the Minotaur", location_zh: "弥诺陶洛斯的诞生", text_en: "Circe, a lesser daughter of the sun god banished to the island of Aiaia for witchcraft, is summoned to Crete by her sister Pasiphaë, the queen, to help at the birth of the monstrous child she has conceived with a bull. Circe delivers the Minotaur, and there meets the craftsman Daedalus, the one person who shows her kindness.", text_zh: "喀耳刻是太阳神不受宠的女儿，因为施行巫术被放逐到埃埃亚岛。她的姐姐、克里特王后帕西淮召她来克里特，帮忙生下与公牛所怀的怪物孩子。喀耳刻接生了弥诺陶洛斯，也在这里遇到了工匠代达罗斯，唯一对她好的人。", highlight_en: ["Minotaur"], highlight_zh: ["弥诺陶洛斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Circe_(novel)" },
  { id: "clyt-s1", kind: "scene", book_id: "clytemnestra", place_ids: ["gr-mycenae"], location: "Throughout", location_zh: "全书", text_en: "Clytemnestra, the fierce Spartan princess, is forced to marry Agamemnon, king of Mycenae, after he murders her first husband and baby. She makes herself a queen, but when he lures their eldest daughter Iphigenia to Aulis and sacrifices her for a wind to Troy, she rules Mycenae alone for ten years and waits for his return.", text_zh: "刚烈的斯巴达公主克吕泰涅斯特拉被迫嫁给迈锡尼国王阿伽门农——他杀了她的第一任丈夫和婴儿。她让自己成了真正的王后；可当他把他们的长女伊菲革涅亚骗到奥利斯、为了驶向特洛伊的顺风把她献祭之后，她独自统治迈锡尼十年，等着他回来。", highlight_en: ["Iphigenia"], highlight_zh: ["伊菲革涅亚"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Clytemnestra_(novel)" },
  { id: "moon-s1", kind: "scene", book_id: "moon-spinners", place_ids: ["gr-samaria"], location: "Opening chapters", location_zh: "开头几章", text_en: "Nicola Ferris, a young Englishwoman working at the embassy in Athens, arrives a day early for a holiday on the south-west coast of Crete and walks up into the White Mountains. In a shepherd's hut she finds Mark Langley, wounded after witnessing a murder, whose young brother Colin has been taken; the trail leads back to her own hotel.", text_zh: "在雅典大使馆工作的年轻英国女子尼古拉·费里斯提前一天来到克里特西南海岸度假，走进了白山。她在一间牧人小屋里发现了受伤的马克·兰利——他目睹了一起谋杀，弟弟科林被人带走了；线索最后指向她自己住的旅馆。", highlight_en: ["White Mountains"], highlight_zh: ["白山"], status: "draft", fact_source: "https://whatmeread.com/tag/the-moon-spinners/" },
  { id: "magic-s1", kind: "scene", book_id: "rough-magic", place_ids: ["gr-corfu-town"], location: "Throughout", location_zh: "全书", text_en: "Lucy Waring, an out-of-work actress, joins her sister at a villa on Corfu, where a famous old actor is living in seclusion. When a fisherman's body washes up and someone fires at a tame dolphin that swims in the bay, Lucy is caught up in a smuggling plot, and the dolphin ends by saving her life.", text_zh: "失业的演员露西·韦林到科孚岛的一座别墅投奔姐姐，那里隐居着一位著名的老演员。一个渔夫的尸体被冲上岸，又有人向海湾里一只温驯的海豚开枪，露西卷进了一桩走私阴谋，最后是那只海豚救了她的命。", highlight_en: ["dolphin"], highlight_zh: ["海豚"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/This_Rough_Magic" },
  { id: "hadrian-s1", kind: "scene", book_id: "hadrian", place_ids: ["gr-hadrian-arch"], location: "Throughout", location_zh: "全书", text_en: "Near death, the Emperor Hadrian writes a long letter to the young Marcus Aurelius, recalling his life: his love of Greece, his years in Athens, where he completed the Olympieion and was initiated at Eleusis, his travels across the empire, and his passion for the Bithynian youth Antinous, whose drowning in the Nile he never recovers from.", text_zh: "临终的哈德良皇帝给少年马可·奥勒留写了一封长信，回顾自己的一生：对希腊的热爱，在雅典的岁月——他在那里建成了奥林匹亚宙斯神庙，在厄琉息斯接受了秘仪——他在帝国各地的巡游，还有他对比提尼亚少年安提诺乌斯的激情；安提诺乌斯溺死在尼罗河里，他再也没有从中恢复过来。", highlight_en: ["Antinous"], highlight_zh: ["安提诺乌斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Memoirs_of_Hadrian" },
  // —— 11-22 quotations from Greek Wikisource, replacing the placeholder scene notes (add_gr3.py) ——
  { id: "odyssey-1", book_id: "odyssey", place_ids: ["gr-ithaca"], location: "Book 9, lines 21–28", location_zh: "第九卷第 21–28 行", text_orig: "ναιετάω δ' Ἰθάκην εὐδείελον· ἐν δ' ὄρος αὐτῇ,\nΝήριτον εἰνοσίφυλλον, ἀριπρεπές· ἀμφὶ δὲ νῆσοι\nπολλαὶ ναιετάουσι μάλα σχεδὸν ἀλλήλῃσι,\nΔουλίχιόν τε Σάμη τε καὶ ὑλήεσσα Ζάκυνθος.\nαὐτὴ δὲ χθαμαλὴ πανυπερτάτη εἰν ἁλὶ κεῖται\nπρὸς ζόφον, αἱ δέ τ' ἄνευθε πρὸς ἠῶ τ' ἠέλιόν τε,\nτρηχεῖ', ἀλλ' ἀγαθὴ κουροτρόφος· οὔ τι ἐγώ γε\nἧς γαίης δύναμαι γλυκερώτερον ἄλλο ἰδέσθαι.", highlight_orig: ["Ἰθάκην"], text_en: "I dwell in clear-seen Ithaca; on it is a mountain,\nNeriton, its leaves shaking, standing out from afar; and round it lie islands,\nmany, very close to one another,\nDoulichion and Same and wooded Zakynthos.\nIthaca itself lies low, furthest of all in the sea\ntowards the dusk, while the others lie apart towards the dawn and the sun;\na rugged land, but a good nurse of young men; for my part\nI can see nothing sweeter than one's own land.", highlight_en: ["Ithaca"], text_zh: "我住在阳光明媚的伊萨卡，岛上有座山，\n涅里托斯山，林木摇曳，远远望去十分醒目；四周有许多岛屿，\n彼此紧紧相邻，\n杜利基昂、萨墨，还有林木茂密的扎昆托斯。\n伊萨卡地势低平，在大海中最远，\n朝着昏暗的西方，其他的岛屿则远远朝着黎明和太阳；\n这地方崎岖，却是养育少年的好地方；在我看来，\n再没有什么比自己的故土更甜美可看的了。", highlight_zh: ["伊萨卡"], translation: "own", status: "draft", checked: "Greek Wikisource, Ὀδύσσεια ι (the edition's line numbers left out), 2026-11-22" },
  { id: "oresteia-1", book_id: "oresteia", place_ids: ["gr-areopagus"], location: "The Eumenides, lines 681–695", location_zh: "《报仇神》第 681–695 行", text_orig: "κλύοιτ᾽ ἂν ἤδη θεσμόν, Ἀττικὸς λεώς,\nπρώτας δίκας κρίνοντες αἵματος χυτοῦ.\nἔσται δὲ καὶ τὸ λοιπὸν Αἰγέως στρατῷ\nαἰεὶ δικαστῶν τοῦτο βουλευτήριον.\nπάγον δ᾽ Ἄρειον τόνδ᾽, Ἀμαζόνων ἕδραν\nσκηνάς θ᾽, ὅτ᾽ ἦλθον Θησέως κατὰ φθόνον\nστρατηλατοῦσαι, καὶ πόλιν νεόπτολιν\nτήνδ᾽ ὑψίπυργον ἀντεπύργωσαν τότε,\nἌρει δ᾽ ἔθυον, ἔνθεν ἔστ᾽ ἐπώνυμος\nπέτρα, πάγος τ᾽ Ἄρειος· ἐν δὲ τῷ σέβας\nἀστῶν φόβος τε ξυγγενὴς τὸ μὴ ἀδικεῖν\nσχήσει τό τ᾽ ἦμαρ καὶ κατ᾽ εὐφρόνην ὁμῶς,\nαὐτῶν πολιτῶν μὴ ᾽πιχραινόντων νόμους\nκακαῖς ἐπιῤῥοαῖσι· βορβόρῳ δ᾽ ὕδωρ\nλαμπρὸν μιαίνων οὔποθ᾽ εὑρήσεις ποτόν.", highlight_orig: ["πάγον δ᾽ Ἄρειον", "πάγος τ᾽ Ἄρειος"], text_en: "Hear now my ordinance, people of Attica,\nyou who judge the first trial for blood shed.\nFor the future too, for the people of Aegeus,\nthis council of judges shall always remain.\nThis Hill of Ares, the seat of the Amazons\nand their tents, when they came in hatred of Theseus\nleading an army, and built up towers against the city,\nthis new city with its high towers,\nand sacrificed to Ares, whence the rock\nis named the Hill of Ares: on it the citizens' awe\nand its kinsman, fear, shall keep them from wrongdoing\nby day and by night alike,\nso long as the citizens themselves do not alter the laws\nwith evil inflows; if you foul clear water\nwith mud you will never find a drink.", highlight_en: ["This Hill of Ares", "the Hill of Ares"], text_zh: "阿提卡的人民啊，现在听我立下的规矩，\n你们是审判第一桩流血案件的人。\n今后，为埃勾斯的子民，\n这个法官的议事会将永远存在。\n这座战神山，从前阿马宗女战士\n怀着对忒修斯的仇恨率军前来时，\n在这里扎营安帐，筑起塔楼对抗这座城，\n这座新建的、塔楼高耸的城，\n她们在这里向战神阿瑞斯献祭，这块岩石由此得名，\n叫做战神山：在这里，市民的敬畏\n和与它同源的恐惧，将使他们不敢作恶，\n无论白天还是黑夜，\n只要市民自己不用恶劣的混流\n去败坏法律；用污泥弄脏清水，\n你就再也找不到可喝的水了。", highlight_zh: ["这座战神山", "叫做战神山"], translation: "own", status: "draft", checked: "Greek Wikisource, Ευμενίδες (the edition's line numbers left out), 2026-11-22" },
  { id: "seven-1", book_id: "seven-thebes", place_ids: ["gr-thebes"], location: "Lines 1–9", location_zh: "第 1–9 行", text_orig: "Κάδμου πολῖται, χρὴ λέγειν τὰ καίρια\nὅστις φυλάσσει πρᾶγος ἐν πρύμνῃ πόλεως\nοἴακα νωμῶν, βλέφαρα μὴ κοιμῶν ὕπνῳ.\nεἰ μὲν γὰρ εὖ πράξαιμεν, αἰτία θεοῦ·\nεἰ δ᾽ αὖθ᾽, ὃ μὴ γένοιτο, συμφορὰ τύχοι,\nἘτεοκλέης ἂν εἷς πολὺς κατὰ πτόλιν\nὑμνοῖθ᾽ ὑπ᾽ ἀστῶν φροιμίοις πολυῤῥόθοις\nοἰμώγμασίν θ᾽, ὧν Ζεὺς ἀλεξητήριος\nἐπώνυμος γένοιτο Καδμείων πόλει.", highlight_orig: ["Κάδμου πολῖται", "Καδμείων πόλει"], text_en: "Citizens of Cadmus, he must speak what the moment needs\nwho guards the city's affairs at the stern,\nturning the tiller, not letting his eyes close in sleep.\nFor if we fare well, the cause is a god's;\nbut if, which may it not happen, disaster strikes,\nEteocles alone would be the name, many times over, through the city,\nchanted by the citizens in loud preludes\nand laments; from which may Zeus the Defender,\ntrue to his name, defend the city of the Cadmeans.", highlight_en: ["Citizens of Cadmus", "the city of the Cadmeans"], text_zh: "卡德摩斯的公民们，谁在城邦的船尾\n守护着国事、掌着舵，\n不让眼睛合上入睡，谁就应当说合时宜的话。\n如果我们一切顺利，那是神的功劳；\n可要是——但愿不会——遭了灾祸，\n全城上下，人们就只会一遍遍喊着埃特奥克勒斯一个人的名字，\n用嘈杂的序曲\n和哀号来唱他；愿守护者宙斯\n不负其名，保护卡德摩斯人的城邦免遭此祸。", highlight_zh: ["卡德摩斯的公民们", "卡德摩斯人的城邦"], translation: "own", status: "draft", checked: "Greek Wikisource, Επτά επί Θήβας (the edition's line numbers left out), 2026-11-22" },
  { id: "oedipus-1", book_id: "oedipus-rex", place_ids: ["gr-thebes"], location: "Lines 1–8", location_zh: "第 1–8 行", text_orig: "ὦ τέκνα, Κάδμου τοῦ πάλαι νέα τροφή,\nτίνας ποθ᾽ ἕδρας τάσδε μοι θοάζετε\nἱκτηρίοις κλάδοισιν ἐξεστεμμένοι;\nπόλις δ᾽ ὁμοῦ μὲν θυμιαμάτων γέμει,\nὁμοῦ δὲ παιάνων τε καὶ στεναγμάτων·\nἁγὼ δικαιῶν μὴ παρ᾽ ἀγγέλων, τέκνα,\nἄλλων ἀκούειν αὐτὸς ὧδ᾽ ἐλήλυθα,\nὁ πᾶσι κλεινὸς Οἰδίπους καλούμενος.", highlight_orig: ["Κάδμου τοῦ πάλαι", "πόλις"], text_en: "My children, newest brood of ancient Cadmus,\nwhy do you sit here before me like this,\ncrowned with the suppliant's branches?\nThe city is full of incense at once,\nand full of hymns of healing and of groans;\nand I, thinking it not right to hear of this from messengers,\nfrom others, my children, have come here myself,\nI, Oedipus, whom all men call renowned.", highlight_en: ["ancient Cadmus", "The city"], text_zh: "孩子们，古老的卡德摩斯的新一代，\n你们为什么这样坐在我面前，\n手持缠着羊毛的求援树枝？\n全城一时间弥漫着香烟，\n又响彻着求医的颂歌和呻吟；\n孩子们，我认为不该从别人、从信使那里听说这些，\n所以亲自来了，\n我，人人都称为声名远扬的俄狄浦斯。", highlight_zh: ["古老的卡德摩斯", "全城"], translation: "own", status: "draft", checked: "Greek Wikisource, Οιδίπους Τύραννος (the edition's line numbers left out), 2026-11-22" },
  { id: "antigone-1", book_id: "antigone", place_ids: ["gr-thebes"], location: "Parodos, lines 100–109", location_zh: "进场歌第 100–109 行", text_orig: "ἀκτὶς ἀελίου, τὸ κάλλιστον ἑπταπύλῳ φανὲν\nΘήβᾳ τῶν προτέρων φάος,\nἐφάνθης ποτ᾽, ὦ χρυσέας\nἁμέρας βλέφαρον,\nΔιρκαίων ὑπὲρ ῥεέθρων μολοῦσα,\nτὸν λεύκασπιν Ἀργόθεν ἐκβάντα φῶτα πανσαγίᾳ\nφυγάδα πρόδρομον ὀξυτέρῳ κινήσασα χαλινῷ·", highlight_orig: ["ἑπταπύλῳ", "Θήβᾳ"], text_en: "Beam of the sun, fairest light that ever shone\non seven-gated Thebes of all before,\nyou have shone at last, eye of golden day,\ncoming over the streams of Dirce,\nyou who drove headlong in flight, with a sharper bridle,\nthe man of the white shield who came from Argos in full armour.", highlight_en: ["seven-gated Thebes"], text_zh: "太阳的光芒，照耀七门的底比斯的\n最美的光，胜过从前的一切，\n金色白昼的眼睛啊，你终于照临了，\n越过狄尔刻的溪流而来，\n你用更锐利的嚼铁驱赶那个\n从阿尔戈斯全副武装而来的白盾之人，叫他仓皇奔逃。", highlight_zh: ["七门的底比斯"], translation: "own", status: "draft", checked: "Greek Wikisource, Αντιγόνη (the edition's line numbers left out), 2026-11-22" },
  { id: "colonus-1", book_id: "oedipus-colonus", place_ids: ["gr-colonus"], location: "First stasimon, lines 668–680", location_zh: "第一合唱歌第 668–680 行", text_orig: "εὐίππου, ξένε, τᾶσδε χώρας\nἵκου τὰ κράτιστα γᾶς ἔπαυλα,\nτὸν ἀργῆτα Κολωνόν, ἔνθ᾽\nἁ λίγεια μινύρεται\nθαμίζουσα μάλιστ᾽ ἀηδὼν\nχλωραῖς ὑπὸ βάσσαις,\nτὸν οἰνωπὸν ἔχουσα κισσὸν\nκαὶ τὰν ἄβατον θεοῦ\nφυλλάδα μυριόκαρπον ἀνήλιον\nἀνήνεμόν τε πάντων\nχειμώνων· ἵν᾽ ὁ βακχιώτας\nἀεὶ Διόνυσος ἐμβατεύει\nθεαῖς ἀμφιπολῶν τιθήναις.", highlight_orig: ["τὸν ἀργῆτα Κολωνόν"], text_en: "Stranger, you have come to the finest dwelling on earth\nin this land of fine horses,\nto shining Colonus, where\nthe clear-voiced nightingale\nmost often sings her lament\nin the green glades,\nkeeping to the wine-dark ivy\nand the god's untrodden\nfoliage, rich in fruit, sunless\nand sheltered from the wind\nof every storm; where the reveller\nDionysus ever walks,\nattending the nymphs who nursed him.", highlight_en: ["shining Colonus"], text_zh: "客人哪，你来到了这片良马之乡\n大地上最好的住处，\n来到了白亮的科罗诺斯，在这里\n声音清亮的夜莺\n最常在绿色的林谷里\n低声悲啼，\n栖息在酒色的常春藤间，\n栖息在神的那片不可践踏的\n果实累累的树丛里，那里不见阳光，\n任何风暴的风\n也吹不进去；在这里，狂欢的\n狄俄尼索斯永远漫步，\n陪伴着哺育他的女神们。", highlight_zh: ["白亮的科罗诺斯"], translation: "own", status: "draft", checked: "Greek Wikisource, Οιδίπους επί Κολωνώ (the edition's line numbers left out), 2026-11-22" },
  { id: "medea-1", book_id: "medea", place_ids: ["gr-corinth"], location: "Lines 1–15", location_zh: "第 1–15 行", text_orig: "Εἴθ’ ὤφελ’ Ἀργοῦς μὴ διαπτάσθαι σκάφος\nΚόλχων ἐς αἶαν κυανέας Συμπληγάδας,\nμηδ’ ἐν νάπαισι Πηλίου πεσεῖν ποτε\nτμηθεῖσα πεύκη, μηδ’ ἐρετμῶσαι χέρας\nἀνδρῶν ἀρίστων. οἳ τὸ πάγχρυσον δέρας\nΠελίᾳ μετῆλθον. οὐ γὰρ ἂν δέσποιν’ ἐμὴ\nΜήδεια πύργους γῆς ἔπλευσ’ Ἰωλκίας\nἔρωτι θυμὸν ἐκπλαγεῖσ’ Ἰάσονος·\nοὐδ’ ἂν κτανεῖν πείσασα Πελιάδας κόρας\nπατέρα κατῴκει τήνδε γῆν Κορινθίαν\nξὺν ἀνδρὶ καὶ τέκνοισιν, ἁνδάνουσα μὲν\nφυγῇ πολιτῶν ὧν ἀφίκετο χθόνα,\nαὐτή τε πάντα ξυμφέρουσ’ Ἰάσονι·\nἥπερ μεγίστη γίγνεται σωτηρία,\nὅταν γυνὴ πρὸς ἄνδρα μὴ διχοστατῇ.", highlight_orig: ["τήνδε γῆν Κορινθίαν"], text_en: "If only the hull of the Argo had never flown\nthrough the dark Clashing Rocks to the land of the Colchians,\nnor the pine had ever fallen, cut in the glens of Pelion,\nnor put oars into the hands\nof the best of men, who went to fetch the all-golden fleece\nfor Pelias! For then my mistress\nMedea would not have sailed to the towers of the land of Iolcus,\nher heart struck with love for Jason;\nnor, having persuaded the daughters of Pelias to kill\ntheir father, would she be living in this land of Corinth\nwith her husband and children, pleasing\nthe citizens of the land she came to in her exile,\nand herself in all things at one with Jason;\nwhich is the greatest safety there is,\nwhen a wife does not stand apart from her husband.", highlight_en: ["this land of Corinth"], text_zh: "但愿阿尔戈号的船身从没有飞越\n那暗蓝的撞岩，驶向科尔基斯人的土地，\n但愿那松树从没有在珀利翁山谷里\n被砍倒，也从没有给那些英雄好汉\n装上船桨，让他们去为珀利阿斯\n取那金羊毛！那样的话，我的女主人\n美狄亚就不会航行到伊俄尔科斯的城楼下，\n她的心也不会被对伊阿宋的爱情击中；\n她也不会劝说珀利阿斯的女儿们杀死父亲，\n如今住在这科林斯的土地上，\n和丈夫孩子在一起，讨得\n她流亡来到的这片土地上的市民的欢心，\n自己也事事顺着伊阿宋；\n这是最大的保障，\n当妻子不与丈夫离心的时候。", highlight_zh: ["这科林斯的土地"], translation: "own", status: "draft", checked: "Greek Wikisource, Μήδεια (the edition's line numbers left out), 2026-11-22" },
  { id: "bacchae-1", book_id: "bacchae", place_ids: ["gr-thebes"], location: "Lines 1–5", location_zh: "第 1–5 行", text_orig: "ἥκω Διὸς παῖς τήνδε Θηβαίων χθόνα\nΔιόνυσος, ὃν τίκτει ποθ᾽ ἡ Κάδμου κόρη\nΣεμέλη λοχευθεῖσ᾽ ἀστραπηφόρῳ πυρί·\nμορφὴν δ᾽ ἀμείψας ἐκ θεοῦ βροτησίαν\nπάρειμι Δίρκης νάματ᾽ Ἰσμηνοῦ θ᾽ ὕδωρ.", highlight_orig: ["τήνδε Θηβαίων χθόνα"], text_en: "I have come, the son of Zeus, to this land of the Thebans,\nDionysus, whom once the daughter of Cadmus bore,\nSemele, delivered by the lightning-bearing fire;\nand having changed my form from god to mortal\nI am here by the streams of Dirce and the water of Ismenus.", highlight_en: ["this land of the Thebans"], text_zh: "我来了，宙斯的儿子，来到这底比斯人的土地，\n我是狄俄尼索斯，卡德摩斯的女儿塞墨勒\n当年在闪电的火焰中生下了我；\n我把神的模样换成凡人的形貌，\n来到狄尔刻的溪流和伊斯墨诺斯河边。", highlight_zh: ["这底比斯人的土地"], translation: "own", status: "draft", checked: "Greek Wikisource, Βάκχαι, 2026-11-22" },
  { id: "iphigenia-1", book_id: "iphigenia-aulis", place_ids: ["gr-aulis"], location: "Prologue, lines 87–93", location_zh: "开场第 87–93 行", text_orig: "ἠθροισμένου δὲ καὶ ξυνεστῶτος στρατοῦ\nἥμεσθ᾽ ἀπλοίᾳ χρώμενοι κατ᾽ Αὐλίδα.\nΚάλχας δ᾽ ὁ μάντις ἀπορίᾳ κεχρημένοις\nἀνεῖλεν Ἰφιγένειαν ἣν ἔσπειρ᾽ ἐγὼ\nἈρτέμιδι θῦσαι τῇ τόδ᾽ οἰκούσῃ πέδον,\nκαὶ πλοῦν τ᾽ ἔσεσθαι καὶ κατασκαφὰς Φρυγῶν\nθύσασι, μὴ θύσασι δ᾽ οὐκ εἶναι τάδε.", highlight_orig: ["κατ᾽ Αὐλίδα", "Ἀρτέμιδι θῦσαι τῇ τόδ᾽ οἰκούσῃ πέδον"], text_en: "When the army had gathered and assembled,\nwe sat at Aulis, unable to sail.\nCalchas the prophet, as we were at a loss,\ndeclared that Iphigenia, whom I fathered,\nmust be sacrificed to Artemis, who dwells on this ground,\nand that we would have our voyage and the overthrow of the Phrygians\nif we sacrificed her, and if we did not, none of this.", highlight_en: ["Aulis", "Artemis, who dwells on this ground"], text_zh: "大军集结完毕，\n我们却在奥利斯困住了，无法起航。\n我们走投无路时，先知卡尔卡斯\n宣布说，必须把我生的伊菲革涅亚\n献祭给住在这片土地上的阿耳忒弥斯，\n献祭了，就能起航，就能摧毁弗里基亚人；\n不献祭，这一切就都不会有。", highlight_zh: ["奥利斯", "住在这片土地上的阿耳忒弥斯"], translation: "own", status: "draft", checked: "Greek Wikisource, Ιφιγένεια εν Αυλίδι (the edition's line numbers left out), 2026-11-22" },
  { id: "lysistrata-1", book_id: "lysistrata", place_ids: ["gr-acropolis"], location: "Lines 175–179", location_zh: "第 175–179 行", text_orig: "ἀλλ᾽ ἔστι καὶ τοῦτ᾽ εὖ παρεσκευασμένον·\nκαταληψόμεθα γὰρ τὴν ἀκρόπολιν τήμερον.\nταῖς πρεσβυτάταις γὰρ προστέτακται τοῦτο δρᾶν,\nἕως ἂν ἡμεῖς ταῦτα συντιθώμεθα,\nθύειν δοκούσαις καταλαβεῖν τὴν ἀκρόπολιν.", highlight_orig: ["τὴν ἀκρόπολιν"], text_en: "But that too has been well prepared:\nwe'll seize the Acropolis today.\nThe oldest women have been given the job of doing it:\nwhile we are coming to terms here,\nthey are to seize the Acropolis, pretending to sacrifice.", highlight_en: ["the Acropolis"], text_zh: "这一点也早已安排好了：\n我们今天就占领卫城。\n最年长的妇女们已经接到命令去办这件事：\n趁我们在这里商量的时候，\n她们假装去献祭，把卫城占领下来。", highlight_zh: ["卫城"], translation: "own", status: "draft", checked: "Greek Wikisource, Λυσιστράτη (the edition's line numbers left out), 2026-11-22" },
  { id: "histories-1", book_id: "histories", place_ids: ["gr-thermopylae"], location: "Book 7, 225–226", location_zh: "第七卷第 225–226 节", text_orig: "ὁ δὲ κολωνὸς ἐστὶ ἐν τῇ ἐσόδῳ, ὅκου νῦν ὁ λίθινος λέων ἕστηκε ἐπὶ Λεωνίδῃ.\n…\nΛακεδαιμονίων δὲ καὶ Θεσπιέων τοιούτων γενομένων ὅμως λέγεται ἀνὴρ ἄριστος γενέσθαι Σπαρτιήτης Διηνέκης· τὸν τόδε φασὶ εἰπεῖν τὸ ἔπος πρὶν ἢ συμμῖξαι σφέας τοῖσι Μήδοισι, πυθόμενον πρός τευ τῶν Τρηχινίων ὡς ἐπεὰν οἱ βάρβαροι ἀπίωσι τὰ τοξεύματα, τὸν ἥλιον ὑπὸ τοῦ πλήθεος τῶν ὀιστῶν ἀποκρύπτουσι· τοσοῦτο πλῆθος αὐτῶν εἶναι. τὸν δὲ οὐκ ἐκπλαγέντα τούτοισι εἰπεῖν ἐν ἀλογίῃ ποιεύμενον τὸ Μήδων πλῆθος, ὡς πάντα σφι ἀγαθὰ ὁ Τρηχίνιος ξεῖνος ἀγγέλλοι, εἰ ἀποκρυπτόντων τῶν Μήδων τὸν ἥλιον ὑπὸ σκιῇ ἔσοιτο πρὸς αὐτοὺς ἡ μάχη καὶ οὐκ ἐν ἡλίῳ.", highlight_orig: ["ὁ δὲ κολωνὸς ἐστὶ ἐν τῇ ἐσόδῳ"], text_en: "The hillock is at the entrance of the pass, where the stone lion now stands in honour of Leonidas.\n…\nThough the Lacedaemonians and Thespians proved themselves such men, the bravest of all, it is said, was the Spartan Dieneces. They say he spoke this word before they closed with the Medes, when he learned from one of the Trachinians that when the barbarians let fly their arrows they hid the sun by the multitude of their shafts, so great was their number. He was not dismayed by this, but, making light of the multitude of the Medes, said that their Trachinian friend brought them nothing but good news, for if the Medes hid the sun they would fight them in the shade and not in the sun.", highlight_en: ["The hillock is at the entrance of the pass"], text_zh: "那座小山丘就在关口的入口处，如今那里立着一尊为列奥尼达而立的石狮子。\n…\n拉刻代蒙人和忒斯皮埃人虽然都表现得如此英勇，据说其中最勇敢的是斯巴达人狄耶涅凯斯。据说在同米底人交锋之前，他从一个特拉基斯人那里听说，蛮族人一放箭，箭多得能把太阳遮住，他们的人数就是这么多。他并没有被吓住，反而毫不把米底人的人多放在眼里，说这位特拉基斯朋友给他们带来的全是好消息：既然米底人能遮住太阳，那他们就可以在阴凉里而不是在太阳底下作战了。", highlight_zh: ["那座小山丘就在关口的入口处"], translation: "own", status: "draft", checked: "Greek Wikisource, Ιστορίαι (Ηροδότου)/Πολύμνια (the section marker [226.2] left out), 2026-11-22" },
  { id: "thucydides-1", book_id: "thucydides", place_ids: ["gr-kerameikos"], location: "Book 2, 34", location_zh: "第二卷第 34 节", text_orig: "τιθέασιν οὖν ἐς τὸ δημόσιον σῆμα, ὅ ἐστιν ἐπὶ τοῦ καλλίστου προαστείου τῆς πόλεως, καὶ αἰεὶ ἐν αὐτῷ θάπτουσι τοὺς ἐκ τῶν πολέμων, πλήν γε τοὺς ἐν Μαραθῶνι· ἐκείνων δὲ διαπρεπῆ τὴν ἀρετὴν κρίναντες αὐτοῦ καὶ τὸν τάφον ἐποίησαν.\n…\nἐπὶ δ’ οὖν τοῖς πρώτοις τοῖσδε Περικλῆς ὁ Ξανθίππου ᾑρέθη λέγειν. καὶ ἐπειδὴ καιρὸς ἐλάμβανε, προελθὼν ἀπὸ τοῦ σήματος ἐπὶ βῆμα ὑψηλὸν πεποιημένον, ὅπως ἀκούοιτο ὡς ἐπὶ πλεῖστον τοῦ ὁμίλου, ἔλεγε τοιάδε.", highlight_orig: ["τὸ δημόσιον σῆμα"], text_en: "So they lay them in the public burial ground, which is in the most beautiful suburb of the city, and there they always bury those who fall in war, except those at Marathon; for them, judging their valour outstanding, they made the tomb on the spot.\n…\nOver these first dead, then, Pericles son of Xanthippus was chosen to speak. And when the moment came, he went forward from the tomb onto a high platform that had been built so that he could be heard by as much of the crowd as possible, and spoke as follows.", highlight_en: ["the public burial ground"], text_zh: "于是他们把遗骨安葬在公墓里，公墓位于城郊最美的地方；战死的人一向都葬在这里，只有马拉松的阵亡者例外：人们认为那些人的英勇格外出众，就在当地为他们修了坟墓。\n…\n为这第一批阵亡者致辞的，被选中的是克珊西波斯之子伯里克利。时候一到，他从墓地走上一座高台——高台是特意搭起来的，好让尽可能多的人听见——发表了如下的演说。", highlight_zh: ["公墓"], translation: "own", status: "draft", checked: "Greek Wikisource, Ιστορία του Πελοποννησιακού Πολέμου/Β, 2026-11-22" },
  { id: "socrates-1", book_id: "socrates", place_ids: ["gr-agora"], location: "Apology 17c–d", location_zh: "《申辩篇》17c–d", text_orig: "καὶ μέντοι καὶ πάνυ, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο ὑμῶν δέομαι καὶ παρίεμαι· ἐὰν διὰ τῶν αὐτῶν λόγων ἀκούητέ μου ἀπολογουμένου δι᾽ ὧνπερ εἴωθα λέγειν καὶ ἐν ἀγορᾷ ἐπὶ τῶν τραπεζῶν, ἵνα ὑμῶν πολλοὶ ἀκηκόασι, καὶ ἄλλοθι, μήτε θαυμάζειν μήτε θορυβεῖν τούτου ἕνεκα. ἔχει γὰρ οὑτωσί. νῦν ἐγὼ πρῶτον ἐπὶ δικαστήριον ἀναβέβηκα, ἔτη γεγονὼς ἑβδομήκοντα·", highlight_orig: ["ἐν ἀγορᾷ ἐπὶ τῶν τραπεζῶν"], text_en: "And indeed, men of Athens, I very much ask and beg this of you: if you hear me making my defence with the same words I am used to speaking in the agora, at the bankers' tables, where many of you have heard me, and elsewhere, do not be surprised or make a disturbance on that account. For this is how it is: now for the first time I have come up before a court, at the age of seventy.", highlight_en: ["in the agora, at the bankers' tables"], text_zh: "而且，雅典人啊，我非常恳切地请求你们这一点：如果你们听见我为自己辩护时，用的还是我平常在市集上、在钱庄的桌子旁——你们许多人都在那里听过我说话——以及在别处惯用的那些话，请不要为此感到惊讶，也不要喧哗。因为情形是这样的：我活到七十岁，这是头一回上法庭。", highlight_zh: ["在市集上、在钱庄的桌子旁"], translation: "own", status: "draft", checked: "Greek Wikisource, Απολογία Σωκράτους (Πλάτων) (the Stephanus letter 'd' left out), 2026-11-22" },
  { id: "republic-1", book_id: "republic", place_ids: ["gr-piraeus"], location: "Book 1, 327a–b", location_zh: "第一卷 327a–b", text_orig: "κατέβην χθὲς εἰς Πειραιᾶ μετὰ Γλαύκωνος τοῦ Ἀρίστωνος προσευξόμενός τε τῇ θεῷ καὶ ἅμα τὴν ἑορτὴν βουλόμενος θεάσασθαι τίνα τρόπον ποιήσουσιν ἅτε νῦν πρῶτον ἄγοντες. καλὴ μὲν οὖν μοι καὶ ἡ τῶν ἐπιχωρίων πομπὴ ἔδοξεν εἶναι, οὐ μέντοι ἧττον ἐφαίνετο πρέπειν ἣν οἱ Θρᾷκες ἔπεμπον. προσευξάμενοι δὲ καὶ θεωρήσαντες ἀπῇμεν πρὸς τὸ ἄστυ.", highlight_orig: ["εἰς Πειραιᾶ"], text_en: "I went down yesterday to the Piraeus with Glaucon, son of Ariston, to pray to the goddess and also because I wanted to see how they would hold the festival, since they were holding it for the first time. I thought the procession of the local people was fine, but the one the Thracians sent seemed no less fitting. When we had prayed and watched, we set off back to the city.", highlight_en: ["the Piraeus"], text_zh: "昨天我和阿里斯通的儿子格劳孔一起下到比雷埃夫斯港，去向女神祈祷，同时也想看看他们怎样举办这个节日，因为这是他们第一次举办。我觉得本地人的游行队伍很好看，色雷斯人派出的队伍也同样出色。我们祈祷完、看完之后，就动身回城里去。", highlight_zh: ["比雷埃夫斯港"], translation: "own", status: "draft", checked: "Greek Wikisource, Πολιτεία/Α (the Stephanus marker [327b] left out), 2026-11-22" },
  { id: "plutarch-1", book_id: "plutarch", place_ids: ["gr-chaeronea"], location: "Life of Demosthenes, chapter 2", location_zh: "《德摩斯梯尼传》第二章", text_orig: "ἡμεῖς δὲ μικρὰν μὲν οἰκοῦντες πόλιν, καὶ ἵνα μὴ μικροτέρα γένηται φιλοχωροῦντες, ἐν δὲ Ῥώμῃ καὶ ταῖς περὶ τὴν Ἰταλίαν διατριβαῖς οὐ σχολῆς οὔσης γυμνάζεσθαι περὶ τὴν Ῥωμαϊκὴν διάλεκτον ὑπὸ χρειῶν πολιτικῶν καὶ τῶν διὰ φιλοσοφίαν πλησιαζόντων, ὀψέ ποτε καὶ πόρρω τῆς ἡλικίας ἠρξάμεθα Ῥωμαϊκοῖς συντάγμασιν ἐντυγχάνειν, καὶ πρᾶγμα θαυμαστὸν μέν, ἀλλ' ἀληθὲς ἐπάσχομεν.", highlight_orig: ["μικρὰν μὲν οἰκοῦντες πόλιν"], text_en: "But as for me, I live in a small city, and I stay in it gladly so that it may not become smaller; and in Rome and my stays in Italy I had no leisure to practise the Roman language because of public business and the people who came to me for philosophy, so that it was late, and well on in years, that I began to read Roman writings; and something remarkable, but true, happened to me.", highlight_en: ["I live in a small city"], text_zh: "至于我，我住在一座小城里，并且乐意住在那里，免得它变得更小；在罗马和意大利逗留期间，我忙于公务，又要应付那些来向我求教哲学的人，没有闲暇练习罗马人的语言，所以直到很晚、年纪已大，我才开始读罗马人的著作；于是我有了一种奇妙但真实的体验。", highlight_zh: ["我住在一座小城里"], translation: "own", status: "draft", checked: "Greek Wikisource, Βίοι Παράλληλοι/Δημοσθένης, 2026-11-22" },
  { id: "eroto-1", book_id: "erotokritos", place_ids: ["gr-sitia"], location: "Part V, lines 1535–1540", location_zh: "第五部第 1535–1540 行", text_orig: "ΒΙΤΣΕΝΤΖΟΣ είν' ο Ποιητής, και στη Γενιάν ΚΟΡΝΑΡΟΣ,\nπου να βρεθεί ακριμάτιστος, σα θα τον πάρει ο Χάρος.\nΣτη Στείαν εγεννήθηκε, στη Στείαν ενεθράφη,\nεκεί ήκαμε κ' εκόπιασεν ετούτα που σας γράφει.\nΣτο Κάστρον επαντρεύθηκε, σαν αρμηνεύγει η Φύση,\nτο τέλος του έχει να γενεί, όπου ο Θεός ορίσει.", highlight_orig: ["Στη Στείαν εγεννήθηκε, στη Στείαν ενεθράφη"], text_en: "Vitsentzos is the poet, and of the family Kornaros,\nmay he be found without sin when Charon takes him.\nIn Sitia he was born, in Sitia he was raised,\nthere he made and laboured over what he writes to you.\nIn Kastro he married, as nature counsels;\nhis end will come wherever God decrees.", highlight_en: ["In Sitia he was born, in Sitia he was raised"], text_zh: "诗人名叫维岑佐斯，家族姓科尔纳罗斯，\n愿卡戎来带走他时，他清白无罪。\n他生在锡蒂亚，长在锡蒂亚，\n在那里写成、辛苦经营了这些献给你们的诗句。\n他在卡斯特罗成了家，正如天性的指引；\n他的结局将在上帝安排的地方。", highlight_zh: ["他生在锡蒂亚，长在锡蒂亚"], translation: "own", status: "draft", checked: "Greek Wikisource, Ερωτόκριτος/Ε (the edition's line number and couplet indent left out), 2026-11-22" },
  { id: "besieged-1", book_id: "free-besieged", place_ids: ["gr-missolonghi"], location: "Second draft, fragments 1–2", location_zh: "第二稿，片段 1–2", text_orig: "Άκρα του τάφου σιωπή στον κάμπο βασιλεύει·\nΛαλεί πουλί, παίρνει σπυρί, κι’ η μάνα το ζηλεύει.\nΤα μάτια η πείνα εμαύρισε· στα μάτια η μάνα μνέει·\nΣτέκει ο Σουλιώτης ο καλός παράμερα και κλαίει:\n«Έρμο τουφέκι σκοτεινό, τί σ’ έχω γω στο χέρι;\nΟπού συ μούγινες βαρύ κι’ ο Αγαρηνός το ξέρει.»\n…\nΤο Μεσολόγγι έπεσε την άνοιξη· ο ποιητής παρασταίνει την Φύση, εις τη στιγμή που είναι ωραιότερη, ως μία δύναμη, η οποία, με όλα τ’ άλλα και υλικά και ηθικά ενάντια, προσπαθεί να δειλιάση τους πολιορκημένους·", highlight_orig: ["Το Μεσολόγγι"], text_en: "The silence of the grave reigns over the plain.\nA bird sings, takes a seed, and the mother envies it.\nHunger has blackened their eyes; in the eyes the mother swears;\nthe good Souliot stands aside and weeps:\n'Wretched dark gun, why do I hold you in my hand?\nYou have become heavy to me, and the Hagarene knows it.'\n…\nMissolonghi fell in spring; the poet shows Nature, at the moment when she is loveliest, as a power which, with everything else, material and moral, against them, tries to break the courage of the besieged;", highlight_en: ["Missolonghi"], text_zh: "坟墓般的死寂笼罩着原野。\n鸟儿啼叫着啄起一粒种子，母亲都羡慕它。\n饥饿使人的眼睛发黑；母亲凭眼睛起誓；\n善良的苏利人站在一旁哭泣：\n“可怜的黑沉沉的枪啊，我把你握在手里做什么？\n你在我手里变得这么沉重，阿加尔的子孙都知道。”\n…\n迈索隆吉翁是在春天陷落的；诗人把大自然表现为一种力量：在她最美的时刻，当一切物质的和精神的东西都与被围者作对时，她也设法动摇他们的勇气；", highlight_zh: ["迈索隆吉翁"], translation: "own", status: "draft", checked: "Greek Wikisource, Οι Ελεύθεροι Πολιορκημένοι/σχεδίασμα Β, 2026-11-22" },
  { id: "cavafy-1", book_id: "cavafy", place_ids: ["gr-ithaca"], location: "'Ithaka'", location_zh: "《伊萨卡》", text_orig: "Σα βγεις στον πηγαιμό για την Ιθάκη,\nνα εύχεσαι νάναι μακρύς ο δρόμος,\nγεμάτος περιπέτειες, γεμάτος γνώσεις.\n…\nΠάντα στον νου σου νάχεις την Ιθάκη.\nΤο φθάσιμον εκεί είν' ο προορισμός σου.\nΑλλά μη βιάζεις το ταξίδι διόλου.\nΚαλλίτερα χρόνια πολλά να διαρκέσει·\nκαι γέρος πια ν' αράξεις στο νησί,\nπλούσιος με όσα κέρδισες στον δρόμο,\nμη προσδοκώντας πλούτη να σε δώσει η Ιθάκη.\nΗ Ιθάκη σ' έδωσε το ωραίο ταξίδι.\nΧωρίς αυτήν δεν θάβγαινες στον δρόμο.\nΑλλο δεν έχει να σε δώσει πια.\nΚι αν πτωχική την βρεις, η Ιθάκη δεν σε γέλασε.\nΕτσι σοφός που έγινες, με τόση πείρα,\nήδη θα το κατάλαβες οι Ιθάκες τι σημαίνουν.", highlight_orig: ["Ιθάκη"], text_en: "As you set out on the journey to Ithaka,\npray that the road is long,\nfull of adventures, full of knowledge.\n…\nAlways keep Ithaka in your mind.\nTo arrive there is your destination.\nBut do not hurry the journey at all.\nBetter that it last many years;\nand that you anchor at the island old at last,\nrich with all you have gained on the road,\nnot expecting Ithaka to give you riches.\nIthaka gave you the lovely journey.\nWithout her you would not have set out on the road.\nShe has nothing more to give you.\nAnd if you find her poor, Ithaka has not deceived you.\nWise as you have become, with so much experience,\nyou will have understood by now what Ithakas mean.", highlight_en: ["Ithaka"], text_zh: "当你启程前往伊萨卡，\n但愿你的道路漫长，\n充满冒险，充满见识。\n…\n心里要时时想着伊萨卡。\n抵达那里，是你的目的地。\n可是千万不要催促旅程。\n最好让它延续许多年；\n等你老了，才在那岛上泊岸，\n带着一路上得来的一切财富，\n不必指望伊萨卡给你什么财富。\n伊萨卡给了你这趟美好的旅程。\n没有她，你就不会上路。\n她再没有什么可以给你了。\n如果你发现她贫瘠，伊萨卡并没有欺骗你。\n你已经变得这样智慧，有了这么多阅历，\n此刻你一定已经懂得，一个个伊萨卡意味着什么。", highlight_zh: ["伊萨卡"], translation: "own", status: "draft", checked: "Greek Wikisource, Ιθάκη, 2026-11-22" },
  { id: "karyotakis-1", book_id: "karyotakis", place_ids: ["gr-preveza"], location: "'Preveza', stanzas 1 and 4", location_zh: "《普雷韦扎》第一、四节", text_orig: "Θάνατος είναι οι κάργες που χτυπιούνται\nστους μαύρους τοίχους και τα κεραμύδια,\nθάνατος οι γυναίκες, που αγαπιούνται\nκαθώς να καθαρίζουνε κρεμμύδια.\n…\nΒάσις, Φρουρά, Εξηκονταρχία Πρεβέζης.\nΤην Κυριακή θ' ακούσουμε την μπάντα.\nΕπήρα ένα βιβλιάριο Τραπέζης\nπρώτη κατάθεσις δραχμαί τριάντα.", highlight_orig: ["Πρεβέζης"], text_en: "Death is the jackdaws beating themselves\nagainst the black walls and the roof tiles,\ndeath the women who are loved\nas if they were peeling onions.\n…\nBase, Garrison, Gendarmerie Company of Preveza.\nOn Sunday we shall hear the band.\nI took out a bank book,\nfirst deposit thirty drachmas.", highlight_en: ["Preveza"], text_zh: "死亡是那些寒鸦，撞在\n黑色的墙壁和屋瓦上，\n死亡是那些女人，她们被爱着，\n就像在剥洋葱。\n…\n普雷韦扎基地、卫戍部队、宪兵连。\n星期天我们将去听乐队演奏。\n我办了一本银行存折，\n第一笔存款三十德拉克马。", highlight_zh: ["普雷韦扎"], translation: "own", status: "draft", checked: "Greek Wikisource, Πρέβεζα, 2026-11-22" }
];
